<template><div class="page-container"><el-table :data="tableData" border stripe v-loading="loading"><el-table-column prop="employeeId" label="员工ID"/><el-table-column prop="attendanceDate" label="日期"/><el-table-column prop="attendanceType" label="类型"><template #default="{row}"><el-tag :type="['success','warning','warning','danger','primary'][row.attendanceType]" size="small">{{['正常','迟到','早退','缺勤','加班'][row.attendanceType]}}</el-tag></template></el-table-column></el-table></div></template>
